brightness = 0.06
contrast = 1.25
saturation = 1.35
warmth = 0.08
vignette_amount = 0.65

// @group: Processing Pipeline
contrasted = (c.rgb - 0.5) * contrast + 0.5 + brightness
gray_base = contrasted.r * 0.299 + contrasted.g * 0.587 + contrasted.b * 0.114
saturated = lerp([gray_base, gray_base, gray_base], contrasted, saturation)
